def bee_median(values: list[float]) -> float:
    if not values:
        raise ValueError("median of an empty list is undefined")
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return float(ordered[mid])
    return (ordered[mid - 1] + ordered[mid]) / 2.0
